class Solution {
    data class Move(val dr:Int,val dc:Int,val steps:Int);
    private lateinit var options:Array<MutableList<Move>>;
    private lateinit var selected:Array<Move?>;
    private lateinit var positions:Array<IntArray>;
    private fun valid():Boolean{
        for(time in 1..7){
            val occupied=HashSet<Int>();
            for(i in selected.indices){
                val move=selected[i]!!;
                val steps=minOf(time,move.steps);
                val row=positions[i][0]+move.dr*steps;
                val col=positions[i][1]+move.dc*steps;
                if(!occupied.add(row*10+col))return false
            }
        };
        return true
    };
    private fun dfs(index:Int):Int{
        if(index==selected.size)return if(valid())1 else 0;
        var answer=0;
        for(move in options[index]){
            selected[index]=move;
            answer+=dfs(index+1)
        };
        return answer
    };
    fun countCombinations(pieces:Array<String>,positions:Array<IntArray>):Int{
        this.positions=positions;
        val rook=arrayOf(1 to 0,-1 to 0,0 to 1,0 to -1);
        val bishop=arrayOf(1 to 1,1 to -1,-1 to 1,-1 to -1);
        val queen=rook+bishop;
        options=Array(pieces.size){
            mutableListOf(Move(0,0,0))
        };
        selected=arrayOfNulls(pieces.size);
        for(i in pieces.indices){
            val directions=if(pieces[i]=="rook")rook else if(pieces[i]=="bishop")bishop else queen;
            for((dr,dc) in directions){
                var step=1;
                while(true){
                    val row=positions[i][0]+dr*step;
                    val col=positions[i][1]+dc*step;
                    if(row !in 1..8||col !in 1..8)break;
                    options[i].add(Move(dr,dc,step));
                    step++
                }
            }
        };
        return dfs(0)
    }
}

